def calculate_invoice(customer, orders, discounts, taxes, promo_codes):
    total = 0
    for order in orders:
        if order.status == 'active':
            price = order.base_price
            if customer.tier == 'gold':
                price *= 0.9
            elif customer.tier == 'silver':
                price *= 0.95
            for d in discounts:
                if d.applies_to(order) and d.valid():
                    price -= d.amount
            for code in promo_codes:
                if code.valid and not code.used:
                    price *= (1 - code.pct)
            total += price * (1 + taxes.rate(customer.region))
    return total
```

