public Order processOrder(Request req, User user, DB db) {
    if (req == null || user == null) throw new IllegalArgumentException();
    if (!user.hasPermission("order")) return null;
    Order o = db.find(req.orderId);
    if (o.status == PENDING) {
        if (req.action.equals("approve")) { o.approve(); }
        else if (req.action.equals("reject")) { o.reject(req.reason); }
    }
    return db.save(o);
}
